972	// 已成功退款编号优先判定：目标与原因都相同 => duplicate 并返回原退款记录；
973	// 目标或原因任一不同 => conflict。都不再入账。
974	func TestRefundDuplicateAndConflict(t *testing.T) {
975		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1_000_000}})
976		l := openOrFail(t, path)
977		for _, id := range []string{"p1", "p2"} {
978			if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent(id, "aa", "usdc", 100)}}); err != nil {
979				t.Fatal(err)
980			}
981		}
982		first, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "reason A")}})
983		if first.Results[0].Status != StatusRefundSuccess {
984			t.Fatalf("first: %+v", first.Results[0])
985		}
986		balAfter, _ := l.Balance("aa", "usdc")
987	
988		// 完全相同：duplicate，带原退款记录，不再入账。
989		dup, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "reason A")}})
990		d := dup.Results[0]
