func limit(account, asset string, max int64) ChargeLimit {
	return ChargeLimit{Account: account, Asset: asset, MaxCharged: i64p(max)}
}

func TestChargeLimitBasics(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{
